  console.log(`✅ ${insertedStudies.length} Studien erstellt`)

  // ── Glossar ─────────────────────────────────────────────────────────────────
  const glossaryData = [
    { slug: 'rct', term: 'RCT (Randomized Controlled Trial)', definition: 'Eine randomisierte kontrollierte Studie ist der Goldstandard der klinischen Forschung. Teilnehmer werden zufällig verschiedenen Gruppen zugeteilt, um Verzerrungen zu minimieren.', explanation: 'Stell dir vor: Eine Gruppe bekommt Futter A, die andere Futter B – aber wer was bekommt, wird per Zufall entschieden. So stellt man sicher, dass das Ergebnis wirklich durch das Futter und nicht durch andere Faktoren zustande kommt.', category: 'Methodik' },
    { slug: 'meta-analyse', term: 'Meta-Analyse', definition: 'Eine statistische Methode, die Ergebnisse mehrerer unabhängiger Studien zu einem Thema zusammenfasst und analysiert, um zu einer Gesamtaussage zu kommen.', explanation: 'Statt nur eine Studie zu lesen, schaut man sich alle Studien zu einem Thema an und rechnet die Ergebnisse zusammen. Das ist aussagekräftiger als einzelne Studien.', category: 'Methodik' },
    { slug: 'mikrobiom', term: 'Mikrobiom', definition: 'Die Gesamtheit aller Mikroorganismen (Bakterien, Viren, Pilze) in einem bestimmten Lebensraum, insbesondere im Darm. Das Darmmikrobiom spielt eine wichtige Rolle für Verdauung und Immunsystem.', explanation: 'Der Darm ist wie ein kleiner Kosmos aus Milliarden Bakterien. Diese helfen bei der Verdauung, stärken das Immunsystem und können sogar das Verhalten beeinflussen.', category: 'Gesundheit' },
    { slug: 'dha', term: 'DHA (Docosahexaensäure)', definition: 'Eine Omega-3-Fettsäure, die wichtig für Gehirnentwicklung, Sehkraft und Entzündungshemmung ist. Sie kommt vor allem in Fischöl und bestimmten Algen vor.', explanation: 'DHA ist wie "Superfood" für das Gehirn – besonders wichtig für Welpen und ältere Hunde. Es hilft bei der Gehirnentwicklung und kann Gelenkentzündungen lindern.', category: 'Ernährung' },
    { slug: 'epa', term: 'EPA (Eicosapentaensäure)', definition: 'Eine Omega-3-Fettsäure mit entzündungshemmenden Eigenschaften. Wird oft bei Gelenkproblemen und Hauterkrankungen eingesetzt.', explanation: 'EPA wirkt wie ein natürlicher Entzündungshemmer. Es kann helfen, Gelenkschmerzen zu lindern und die Hautgesundheit zu verbessern.', category: 'Ernährung' },
    { slug: 'aafco', term: 'AAFCO (Association of American Feed Control Officials)', definition: 'US-amerikanische Organisation, die Richtlinien für die Nährstoffzusammensetzung von Tiernahrung festlegt. "AAFCO-zertifiziert" bedeutet, dass ein Futter bestimmte Mindeststandards erfüllt.', explanation: 'AAFCO ist wie eine Qualitätskontrolle für Futter. Wenn ein Futter AAFCO-zertifiziert ist, enthält es alle wichtigen Nährstoffe in der richtigen Menge.', category: 'Standards' },
    { slug: 'fediaf', term: 'FEDIAF (European Pet Food Industry Federation)', definition: 'Europäischer Verband der Tiernahrungsindustrie. Legt Richtlinien für die Nährstoffzusammensetzung von Tiernahrung in Europa fest.', explanation: 'FEDIAF ist die europäische Version von AAFCO. Sie legt fest, was europäisches Hundefutter enthalten muss, um als "vollwertig" zu gelten.', category: 'Standards' },
    { slug: 'oxidativer-stress', term: 'Oxidativer Stress', definition: 'Ein Ungleichgewicht zwischen freien Radikalen und Antioxidantien im Körper. Kann zu Zellschäden führen und wird mit Alterungsprozessen und verschiedenen Krankheiten in Verbindung gebracht.', explanation: 'Stell dir vor, dein Körper ist wie ein Auto – freie Radikale sind wie Rost, Antioxidantien wie Rostschutz. Antioxidantien im Futter können helfen, das zu verhindern.', category: 'Gesundheit' },
    { slug: 'praebiotika', term: 'Präbiotika', definition: 'Unverdauliche Nahrungsbestandteile (meist Ballaststoffe), die das Wachstum nützlicher Darmbakterien fördern.', explanation: 'Präbiotika sind wie Dünger für die guten Darmbakterien. Sie helfen diesen Bakterien, sich zu vermehren und gesund zu bleiben.', category: 'Ernährung' },
    { slug: 'probiotika', term: 'Probiotika', definition: 'Lebende Mikroorganismen, die bei Einnahme in ausreichender Menge gesundheitliche Vorteile bieten. Sie sind die "guten" Bakterien selbst.', explanation: 'Probiotika sind wie eine Armee guter Bakterien, die man zur Verstärkung schickt. Sie können helfen, das Gleichgewicht im Darm wiederherzustellen – besonders nach Antibiotika.', category: 'Ernährung' },
    { slug: 'hydrolysiertes-protein', term: 'Hydrolysiertes Protein', definition: 'Protein, das in kleinere Bestandteile (Peptide und Aminosäuren) zerlegt wurde. Dadurch wird es für das Immunsystem weniger erkennbar und kann bei Allergien besser vertragen werden.', explanation: 'Stell dir vor, ein Protein ist wie ein Lego-Bauwerk – hydrolysiert bedeutet, man hat es in einzelne Steine zerlegt. Das Immunsystem erkennt die einzelnen Steine nicht mehr als "Feind".', category: 'Ernährung' },
    { slug: 'eliminationsdiat', term: 'Eliminationsdiät', definition: 'Eine Diät zur Diagnose von Futterallergien, bei der der Hund nur eine einzige Protein- und Kohlenhydratquelle erhält, die er vorher noch nie gefressen hat.', explanation: 'Um herauszufinden, worauf ein Hund allergisch reagiert, gibt man ihm nur ein Futter mit Zutaten, die er noch nie kannte. Wenn die Symptome verschwinden, hat man den Übeltäter gefunden.', category: 'Methodik' },
    { slug: 'eubiosis', term: 'Eubiosis', definition: 'Ein ausgeglichenes, gesundes Darmmikrobiom. Eubiosis fördert Gesundheit und Stoffwechsel.', explanation: 'Eubiosis ist wie ein perfektes Ökosystem im Darm – alle Bakterien arbeiten harmonisch zusammen. Ideal für Verdauung und Immunsystem.', category: 'Gesundheit' },
    { slug: 'dysbiosis', term: 'Dysbiosis', definition: 'Ein Ungleichgewicht im Darmmikrobiom, bei dem schädliche Bakterien überhandnehmen. Kann zu Verdauungsproblemen, Entzündungen und anderen Gesundheitsproblemen führen.', explanation: 'Dysbiosis ist wie ein Ökosystem aus dem Gleichgewicht – schlechte Bakterien vermehren sich zu sehr. Das kann zu Durchfall, Blähungen und sogar Verhaltensänderungen führen.', category: 'Gesundheit' },
    { slug: 'k9pbn', term: 'K9PBN (Canine Plant-Based Nutrition)', definition: 'Vollwertige, ausgewogene pflanzliche Ernährung für Hunde. Erfordert sorgfältige Supplementierung mit Taurin, L-Carnitin und B-Vitaminen.', explanation: 'K9PBN ist der wissenschaftliche Begriff für pflanzliches Hundefutter, das alle Nährstoffe enthält, die Hunde brauchen. Wichtig: Es muss "complete and balanced" sein.', category: 'Ernährung' },
    { slug: 'rmbd', term: 'RMBD (Raw Meat-Based Diet)', definition: 'Rohfutter-Diät mit rohem Fleisch und tierischen Nebenprodukten. Kann kommerziell oder selbst zubereitet sein. Bringt mikrobiologische Risiken mit sich.', explanation: 'RMBD ist der wissenschaftliche Begriff für BARF und andere Rohfutter-Diäten. Rohfutter kann gesund sein, hat aber echte Risiken – Hygiene ist extrem wichtig!', category: 'Ernährung' },
    { slug: 'arachidonsaeure', term: 'Arachidonsäure', definition: 'Eine Omega-6-Fettsäure, die an Entzündungsreaktionen beteiligt ist. Ein hohes Verhältnis von Omega-6 zu Omega-3 kann Entzündungen fördern.', explanation: 'Arachidonsäure ist wie ein "Entzündungs-Auslöser" im Körper. Das Verhältnis zu Omega-3 ist wichtig – zu viel Omega-6 kann Entzündungen fördern, Omega-3 wirkt dagegen.', category: 'Ernährung' },
    { slug: 'fructosamin', term: 'Fructosamin', definition: 'Ein Blutzucker-Marker, der den durchschnittlichen Blutzuckerspiegel der letzten 1–3 Wochen widerspiegelt. Wird zur Diabetes-Diagnose und -überwachung verwendet.', explanation: 'Fructosamin ist wie ein "Blutzucker-Gedächtnis" – es zeigt, wie der Blutzucker in den letzten Wochen war. Hohe Werte können auf schlecht kontrollierten Diabetes hindeuten.', category: 'Gesundheit' },
    { slug: 'verdaulichkeit', term: 'Verdaulichkeit', definition: 'Der Anteil der Nährstoffe, die vom Körper aufgenommen und verwertet werden können. Unterscheidet sich zwischen Nährstoffen und Altersgruppen.', explanation: 'Verdaulichkeit ist wie die "Effizienz" der Verdauung – wie viel von dem, was der Hund isst, landet tatsächlich im Körper? Senioren haben eine andere Verdaulichkeit als jüngere Hunde.', category: 'Ernährung' },
    { slug: 'in-vitro', term: 'In vitro', definition: 'Laboruntersuchungen außerhalb eines lebenden Organismus, z.B. in Reagenzgläsern. Wird zur Simulation von Verdauungsprozessen verwendet.', explanation: 'In vitro bedeutet "im Glas" – Labor-Tests ohne lebende Tiere. In vitro Tests funktionieren gut für Welpen und Erwachsene, aber weniger gut für Senioren.', category: 'Methodik' },
    { slug: 'in-vivo', term: 'In vivo', definition: 'Untersuchungen an lebenden Organismen. Gibt realistischere Ergebnisse als in vitro, ist aber aufwendiger und ethisch komplexer.', explanation: 'In vivo bedeutet "am lebenden Organismus" – echte Tests mit Hunden. Für die Futterentwicklung sind beide Methoden wichtig – in vitro zum Screening, in vivo zur Bestätigung.', category: 'Methodik' },
    { slug: 'cafr', term: 'CAFR (Cutaneous Adverse Food Reaction)', definition: 'Kutane Futtermittelunverträglichkeit – Hautreaktionen, die durch bestimmte Nahrungsbestandteile ausgelöst werden.', explanation: 'CAFR ist der medizinische Begriff für das, was die meisten Hundebesitzer als "Futterallergie" kennen. Nicht immer steckt eine echte Allergie dahinter – manchmal ist es auch eine Intoleranz.', category: 'Gesundheit' },
    { slug: 'cds', term: 'CDS (Canine Cognitive Dysfunction Syndrome)', definition: 'Eine altersbedingte neurodegenerative Erkrankung bei Hunden, vergleichbar mit Alzheimer beim Menschen. Führt zu Orientierungslosigkeit, Schlafproblemen und Verhaltensveränderungen.', explanation: 'CDS ist wie Alzheimer beim Hund – das Gehirn altert und baut ab. Symptome sind Desorientierung, Schlafstörungen oder verändertes Sozialverhalten. Bestimmte Futter können helfen, den Prozess zu verlangsamen.', category: 'Gesundheit' },
    { slug: 'mct', term: 'MCT (mittelkettige Triglyzeride)', definition: 'Eine Fettform, die das Gehirn als alternative Energiequelle nutzen kann. Wird bei kognitiver Dysfunktion bei Senioren eingesetzt.', explanation: 'MCTs sind wie "Turbokerosin" für das alternde Gehirn. Da ein alterndes Gehirn Glukose schlechter verwerten kann, bieten MCTs eine alternative Energiequelle – und können das Denken verbessern.', category: 'Ernährung' },
  ]

